insert into talent_versions (code, name) values ('v1', 'Hero Talent Compass v1')
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'A', '{"en": "Working Style", "ms-MY": "Gaya Kerja", "id-ID": "Gaya Kerja"}'::jsonb, '{"en": "How you naturally work. There is no better or worse answer.", "ms-MY": "Cara anda bekerja secara semula jadi. Tiada jawapan yang lebih baik atau buruk.", "id-ID": "Cara Anda bekerja secara alami. Tidak ada jawaban yang lebih baik atau buruk."}'::jsonb, 0);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'B', '{"en": "Entrepreneurial Readiness", "ms-MY": "Kesediaan Keusahawanan", "id-ID": "Kesiapan Kewirausahaan"}'::jsonb, '{"en": "How you approach opportunity, ownership and getting things done.", "ms-MY": "Cara anda menghadapi peluang, tanggungjawab dan menyiapkan kerja.", "id-ID": "Cara Anda menghadapi peluang, tanggung jawab, dan menyelesaikan pekerjaan."}'::jsonb, 1);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'C', '{"en": "Motivation Map", "ms-MY": "Peta Motivasi", "id-ID": "Peta Motivasi"}'::jsonb, '{"en": "What drives you, and what drains you.", "ms-MY": "Apa yang mendorong anda, dan apa yang melemahkan semangat anda.", "id-ID": "Apa yang mendorong Anda, dan apa yang menurunkan semangat Anda."}'::jsonb, 2);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'D', '{"en": "Success Drive", "ms-MY": "Dorongan Kejayaan", "id-ID": "Dorongan Kesuksesan"}'::jsonb, '{"en": "Your commitment, consistency and resilience — in a sustainable way.", "ms-MY": "Komitmen, konsistensi dan daya tahan anda — secara mampan.", "id-ID": "Komitmen, konsistensi, dan ketahanan Anda — secara berkelanjutan."}'::jsonb, 3);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'E', '{"en": "Real-Estate Scenarios", "ms-MY": "Senario Hartanah", "id-ID": "Skenario Properti"}'::jsonb, '{"en": "Real situations. Every option is a credible way to contribute — choose what you would naturally do.", "ms-MY": "Situasi sebenar. Setiap pilihan adalah cara menyumbang yang munasabah — pilih apa yang anda akan buat secara semula jadi.", "id-ID": "Situasi nyata. Setiap pilihan adalah cara berkontribusi yang masuk akal — pilih apa yang secara alami Anda lakukan."}'::jsonb, 4);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='v1'), 'F', '{"en": "Your Reflection", "ms-MY": "Refleksi Anda", "id-ID": "Refleksi Anda"}'::jsonb, '{"en": "Answer in your own words. There are no right answers.", "ms-MY": "Jawab dengan perkataan anda sendiri. Tiada jawapan yang betul atau salah.", "id-ID": "Jawab dengan kata-kata Anda sendiri. Tidak ada jawaban benar atau salah."}'::jsonb, 5);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='A'), 'A1', 'frequency', '{"en": "In the last 30 days, how often did you start a conversation with someone you did not know well?", "ms-MY": "Dalam 30 hari lepas, berapa kerap anda memulakan perbualan dengan seseorang yang anda tidak kenali rapat?", "id-ID": "Dalam 30 hari terakhir, seberapa sering Anda memulai percakapan dengan orang yang belum Anda kenal dekat?"}'::jsonb, null, 'style.social_energy', false, false, true, null, 0);
