insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E1', 'scenario', '{"en": "You receive a new lead from an online advertisement. The person replies only: \"Send price.\" What would you naturally do next?", "ms-MY": "Anda menerima lead baharu daripada iklan dalam talian. Orang itu hanya membalas: \"Hantar harga.\" Apakah yang anda akan buat seterusnya?", "id-ID": "Anda menerima lead baru dari iklan online. Orang tersebut hanya membalas: \"Kirim harga.\" Apa yang secara alami Anda lakukan berikutnya?"}'::jsonb, null, 'role', false, true, true, null, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E1'), 1, '{"en": "Ask two or three simple questions to understand their needs before recommending anything.", "ms-MY": "Tanya dua tiga soalan mudah untuk memahami keperluan mereka sebelum mengesyorkan apa-apa.", "id-ID": "Ajukan dua tiga pertanyaan sederhana untuk memahami kebutuhan mereka sebelum merekomendasikan apa pun."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E1'), 2, '{"en": "Send a clear project summary, price range and key value points.", "ms-MY": "Hantar ringkasan projek, julat harga dan nilai utama dengan jelas.", "id-ID": "Kirim ringkasan proyek, kisaran harga, dan poin nilai utama dengan jelas."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E1'), 3, '{"en": "Call or message quickly and guide the person toward an appointment.", "ms-MY": "Telefon atau mesej dengan cepat dan bawa mereka ke arah temu janji.", "id-ID": "Telepon atau kirim pesan dengan cepat dan arahkan mereka ke janji temu."}'::jsonb, '{"role.prospector": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E1'), 4, '{"en": "Create a short video or visual that answers the questions buyers usually ask.", "ms-MY": "Cipta video pendek atau visual yang menjawab soalan biasa pembeli.", "id-ID": "Buat video pendek atau visual yang menjawab pertanyaan yang biasa ditanyakan pembeli."}'::jsonb, '{"role.content_creator": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E2', 'scenario', '{"en": "A buyer likes the project but says, \"The price is too high.\" What would you naturally do first?", "ms-MY": "Pembeli suka projek itu tetapi berkata, \"Harganya terlalu tinggi.\" Apakah yang anda akan buat dahulu?", "id-ID": "Pembeli menyukai proyeknya tetapi berkata, \"Harganya terlalu tinggi.\" Apa yang pertama Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E2'), 1, '{"en": "Ask what they are comparing it with and understand their real concern.", "ms-MY": "Tanya mereka membandingkan dengan apa dan fahami kebimbangan sebenar.", "id-ID": "Tanyakan mereka membandingkan dengan apa dan pahami kekhawatiran sebenarnya."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E2'), 2, '{"en": "Explain the value, location, benefits and differences clearly.", "ms-MY": "Terangkan nilai, lokasi, manfaat dan perbezaannya dengan jelas.", "id-ID": "Jelaskan nilai, lokasi, manfaat, dan perbedaannya dengan jelas."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E2'), 3, '{"en": "Explore whether another unit, package or option could help them decide.", "ms-MY": "Terokai sama ada unit, pakej atau pilihan lain boleh membantu mereka membuat keputusan.", "id-ID": "Jajaki apakah unit, paket, atau opsi lain bisa membantu mereka memutuskan."}'::jsonb, '{"role.closer": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E2'), 4, '{"en": "Check whether the concern is about financing ability and coordinate with an authorised financing specialist.", "ms-MY": "Semak sama ada kebimbangan itu berkaitan kemampuan pembiayaan dan berhubung dengan pakar pembiayaan yang diiktiraf.", "id-ID": "Periksa apakah kekhawatirannya soal kemampuan pembiayaan dan koordinasikan dengan spesialis pembiayaan resmi."}'::jsonb, '{"role.financing_coordinator": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E3', 'scenario', '{"en": "You begin the day with no new leads and no appointments. What would you naturally prefer to do?", "ms-MY": "Anda memulakan hari tanpa lead baharu dan tanpa temu janji. Apakah yang anda lebih suka lakukan?", "id-ID": "Anda memulai hari tanpa lead baru dan tanpa janji temu. Apa yang lebih suka Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E3'), 1, '{"en": "Contact people in your existing network and start new conversations.", "ms-MY": "Hubungi orang dalam rangkaian sedia ada dan mulakan perbualan baharu.", "id-ID": "Hubungi orang dalam jaringan Anda dan mulai percakapan baru."}'::jsonb, '{"role.prospector": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E3'), 2, '{"en": "Follow up with older leads who previously showed interest.", "ms-MY": "Susuli lead lama yang pernah menunjukkan minat.", "id-ID": "Tindak lanjuti lead lama yang sebelumnya menunjukkan minat."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E3'), 3, '{"en": "Produce useful content designed to attract future enquiries.", "ms-MY": "Hasilkan kandungan berguna untuk menarik pertanyaan pada masa hadapan.", "id-ID": "Buat konten bermanfaat untuk menarik pertanyaan di masa depan."}'::jsonb, '{"role.content_creator": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E3'), 4, '{"en": "Review a small advertising campaign and test a new audience or message.", "ms-MY": "Semak kempen iklan kecil dan uji audiens atau mesej baharu.", "id-ID": "Tinjau kampanye iklan kecil dan uji audiens atau pesan baru."}'::jsonb, '{"role.advertiser": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E4', 'scenario', '{"en": "You are given the chance to promote a new property project online. Which would you most enjoy doing personally?", "ms-MY": "Anda diberi peluang mempromosikan projek hartanah baharu dalam talian. Yang mana paling anda nikmati lakukan sendiri?", "id-ID": "Anda diberi kesempatan mempromosikan proyek properti baru secara online. Mana yang paling Anda nikmati lakukan sendiri?"}'::jsonb, null, 'role', false, true, true, null, 3);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E4'), 1, '{"en": "Write a useful post or create a short educational video.", "ms-MY": "Tulis pos yang berguna atau cipta video pendidikan pendek.", "id-ID": "Tulis postingan bermanfaat atau buat video edukasi pendek."}'::jsonb, '{"role.content_creator": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E4'), 2, '{"en": "Run a live session and answer questions from viewers.", "ms-MY": "Adakan sesi langsung dan jawab soalan penonton.", "id-ID": "Adakan sesi live dan jawab pertanyaan penonton."}'::jsonb, '{"role.live_host": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E4'), 3, '{"en": "Prepare a structured explanation of the project and the buying process.", "ms-MY": "Sediakan penerangan tersusun tentang projek dan proses pembelian.", "id-ID": "Siapkan penjelasan terstruktur tentang proyek dan proses pembelian."}'::jsonb, '{"role.presenter": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E4'), 4, '{"en": "Design and test an advertising message for a specific audience.", "ms-MY": "Reka dan uji mesej iklan untuk audiens tertentu.", "id-ID": "Rancang dan uji pesan iklan untuk audiens tertentu."}'::jsonb, '{"role.advertiser": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E5', 'scenario', '{"en": "A buyer has shown strong interest but has postponed the next step several times. What would you naturally do?", "ms-MY": "Pembeli menunjukkan minat kuat tetapi menangguhkan langkah seterusnya beberapa kali. Apakah yang anda akan buat?", "id-ID": "Pembeli menunjukkan minat kuat tetapi menunda langkah berikutnya beberapa kali. Apa yang Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 4);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E5'), 1, '{"en": "Have a personal conversation to understand what is holding them back.", "ms-MY": "Berbual secara peribadi untuk memahami apa yang menghalang mereka.", "id-ID": "Lakukan percakapan pribadi untuk memahami apa yang menahan mereka."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E5'), 2, '{"en": "Summarise their needs, the available solution and the next step clearly.", "ms-MY": "Ringkaskan keperluan mereka, penyelesaian yang ada dan langkah seterusnya dengan jelas.", "id-ID": "Rangkum kebutuhan mereka, solusi yang tersedia, dan langkah berikutnya dengan jelas."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E5'), 3, '{"en": "Respectfully ask for a specific decision or an agreed action date.", "ms-MY": "Dengan hormat, minta keputusan khusus atau tarikh tindakan yang dipersetujui.", "id-ID": "Dengan sopan, minta keputusan spesifik atau tanggal tindakan yang disepakati."}'::jsonb, '{"role.closer": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E5'), 4, '{"en": "Check whether documentation or financing uncertainty is causing the delay.", "ms-MY": "Semak sama ada ketidakpastian dokumen atau pembiayaan menyebabkan kelewatan.", "id-ID": "Periksa apakah ketidakpastian dokumen atau pembiayaan menyebabkan penundaan."}'::jsonb, '{"role.financing_coordinator": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E6', 'scenario', '{"en": "You have some spare personal money that is not needed for household essentials, and you are considering putting part of it into an approved team advertising campaign. What would you naturally do?", "ms-MY": "Anda mempunyai lebihan wang peribadi yang tidak diperlukan untuk keperluan asas rumah tangga, dan sedang mempertimbangkan menyalurkan sebahagiannya ke kempen iklan pasukan yang diluluskan. Apakah yang anda akan buat?", "id-ID": "Anda memiliki sisa uang pribadi yang tidak dibutuhkan untuk kebutuhan pokok rumah tangga, dan sedang mempertimbangkan menaruh sebagian ke kampanye iklan tim yang disetujui. Apa yang Anda lakukan?"}'::jsonb, '{"en": "Note: funding a campaign does not guarantee sales or financial returns. Never use essential household funds or borrowed money. Agree the budget, campaign ownership, reporting and lead distribution before funding anything.", "ms-MY": "Nota: membiayai kempen tidak menjamin jualan atau pulangan kewangan. Jangan sekali-kali gunakan wang keperluan asas rumah tangga atau wang pinjaman. Persetujui bajet, pemilikan kempen, pelaporan dan pengagihan lead sebelum membiayai apa-apa.", "id-ID": "Catatan: mendanai kampanye tidak menjamin penjualan atau hasil finansial. Jangan pernah menggunakan dana kebutuhan pokok rumah tangga atau uang pinjaman. Sepakati anggaran, kepemilikan kampanye, pelaporan, dan distribusi lead sebelum mendanai apa pun."}'::jsonb, 'role', false, true, true, null, 5);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E6'), 1, '{"en": "Request the campaign plan, budget limit, reporting method and lead-distribution agreement before deciding.", "ms-MY": "Minta pelan kempen, had bajet, kaedah pelaporan dan persetujuan pengagihan lead sebelum memutuskan.", "id-ID": "Minta rencana kampanye, batas anggaran, metode pelaporan, dan kesepakatan distribusi lead sebelum memutuskan."}'::jsonb, '{"role.team_growth_funder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E6'), 2, '{"en": "Start with a small controlled amount and review the lead quality before increasing it.", "ms-MY": "Mula dengan jumlah kecil yang terkawal dan nilai kualiti lead sebelum menambah.", "id-ID": "Mulai dengan jumlah kecil yang terkendali dan tinjau kualitas lead sebelum menambah."}'::jsonb, '{"role.team_growth_funder": 3, "ent.calculated_risk": 1}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E6'), 3, '{"en": "Prefer to manage and optimise the campaign rather than fund it.", "ms-MY": "Lebih suka mengurus dan mengoptimumkan kempen berbanding membiayainya.", "id-ID": "Lebih suka mengelola dan mengoptimalkan kampanye daripada mendanainya."}'::jsonb, '{"role.advertiser": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E6'), 4, '{"en": "Prefer to work the leads produced instead of managing or funding the advertising.", "ms-MY": "Lebih suka mengusahakan lead yang terhasil berbanding mengurus atau membiayai iklan.", "id-ID": "Lebih suka menggarap lead yang dihasilkan daripada mengelola atau mendanai iklan."}'::jsonb, '{"role.prospector": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E7', 'scenario', '{"en": "A potential buyer likes the property but is worried their loan may not be approved. What would you naturally do?", "ms-MY": "Bakal pembeli suka hartanah itu tetapi bimbang pinjaman mereka mungkin tidak diluluskan. Apakah yang anda akan buat?", "id-ID": "Calon pembeli menyukai propertinya tetapi khawatir pinjamannya tidak disetujui. Apa yang Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 6);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E7'), 1, '{"en": "Listen carefully and understand their main financial concern.", "ms-MY": "Dengar dengan teliti dan fahami kebimbangan kewangan utama mereka.", "id-ID": "Dengarkan dengan saksama dan pahami kekhawatiran finansial utama mereka."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E7'), 2, '{"en": "Explain the general buying process without making promises.", "ms-MY": "Terangkan proses pembelian secara umum tanpa membuat janji.", "id-ID": "Jelaskan proses pembelian secara umum tanpa membuat janji."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E7'), 3, '{"en": "Gather the appropriate basic information and connect them with an authorised financing specialist.", "ms-MY": "Kumpulkan maklumat asas yang sesuai dan hubungkan mereka dengan pakar pembiayaan yang diiktiraf.", "id-ID": "Kumpulkan informasi dasar yang sesuai dan hubungkan mereka dengan spesialis pembiayaan resmi."}'::jsonb, '{"role.financing_coordinator": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E7'), 4, '{"en": "Keep the buyer engaged while coordinating the next responsible step.", "ms-MY": "Kekalkan hubungan dengan pembeli sambil menyelaras langkah seterusnya yang bertanggungjawab.", "id-ID": "Jaga keterlibatan pembeli sambil mengoordinasikan langkah berikutnya yang bertanggung jawab."}'::jsonb, '{"role.closer": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E8', 'scenario', '{"en": "A customer is satisfied after completing a property transaction. What would you naturally do next?", "ms-MY": "Pelanggan berpuas hati selepas melengkapkan transaksi hartanah. Apakah yang anda akan buat seterusnya?", "id-ID": "Pelanggan puas setelah menyelesaikan transaksi properti. Apa yang Anda lakukan berikutnya?"}'::jsonb, null, 'role', false, true, true, null, 7);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E8'), 1, '{"en": "Maintain the relationship and check on their experience.", "ms-MY": "Kekalkan hubungan dan tanya khabar tentang pengalaman mereka.", "id-ID": "Jaga hubungan dan tanyakan bagaimana pengalaman mereka."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E8'), 2, '{"en": "Respectfully ask whether they know anyone else who may need similar help.", "ms-MY": "Dengan hormat, tanya sama ada mereka kenal orang lain yang mungkin perlukan bantuan serupa.", "id-ID": "Dengan sopan, tanyakan apakah mereka kenal orang lain yang mungkin butuh bantuan serupa."}'::jsonb, '{"role.prospector": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E8'), 3, '{"en": "Invite them to share their experience as an approved testimonial or story.", "ms-MY": "Jemput mereka berkongsi pengalaman sebagai testimoni atau cerita yang diluluskan.", "id-ID": "Ajak mereka membagikan pengalaman sebagai testimoni atau cerita yang disetujui."}'::jsonb, '{"role.content_creator": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E8'), 4, '{"en": "Ask whether they know someone who might suit a career in real estate.", "ms-MY": "Tanya sama ada mereka kenal seseorang yang mungkin sesuai untuk kerjaya hartanah.", "id-ID": "Tanyakan apakah mereka kenal seseorang yang mungkin cocok berkarier di properti."}'::jsonb, '{"role.recruiter": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E9', 'scenario', '{"en": "A friend says they are interested in joining real estate but are unsure whether it suits them. What would you naturally do?", "ms-MY": "Seorang kawan berkata dia berminat menyertai bidang hartanah tetapi tidak pasti sama ada ia sesuai untuknya. Apakah yang anda akan buat?", "id-ID": "Seorang teman mengatakan tertarik masuk ke properti tetapi ragu apakah cocok untuknya. Apa yang Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 8);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E9'), 1, '{"en": "Ask about their goals, strengths and reasons for considering it.", "ms-MY": "Tanya tentang matlamat, kekuatan dan sebab mereka mempertimbangkannya.", "id-ID": "Tanyakan tujuan, kekuatan, dan alasan mereka mempertimbangkannya."}'::jsonb, '{"role.recruiter": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E9'), 2, '{"en": "Explain honestly what the work involves, including its challenges.", "ms-MY": "Terangkan dengan jujur apa yang terlibat dalam kerja ini, termasuk cabarannya.", "id-ID": "Jelaskan dengan jujur apa saja pekerjaannya, termasuk tantangannya."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E9'), 3, '{"en": "Invite them to observe an activity or attend an introductory session.", "ms-MY": "Jemput mereka menyaksikan aktiviti atau menghadiri sesi pengenalan.", "id-ID": "Ajak mereka mengamati kegiatan atau menghadiri sesi pengenalan."}'::jsonb, '{"role.recruiter": 2, "role.prospector": 1}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E9'), 4, '{"en": "Offer to teach them one basic skill so they can test their interest.", "ms-MY": "Tawar untuk mengajar satu kemahiran asas supaya mereka boleh menguji minat.", "id-ID": "Tawarkan mengajari satu keterampilan dasar agar mereka bisa menguji minatnya."}'::jsonb, '{"role.coach_trainer": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E10', 'scenario', '{"en": "You have learned about a project with many details, packages and buyer conditions. How would you naturally prepare to explain it?", "ms-MY": "Anda telah mempelajari projek dengan banyak butiran, pakej dan syarat pembeli. Bagaimana anda akan bersedia untuk menerangkannya?", "id-ID": "Anda telah mempelajari proyek dengan banyak detail, paket, dan syarat pembeli. Bagaimana Anda menyiapkan penjelasannya?"}'::jsonb, null, 'role', false, true, true, null, 9);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E10'), 1, '{"en": "Turn the information into a simple visual, post or short video.", "ms-MY": "Ubah maklumat itu kepada visual mudah, pos atau video pendek.", "id-ID": "Ubah informasinya menjadi visual sederhana, postingan, atau video pendek."}'::jsonb, '{"role.content_creator": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E10'), 2, '{"en": "Practise explaining it aloud as though speaking in a live session.", "ms-MY": "Berlatih menerangkannya dengan kuat seolah-olah bercakap dalam sesi langsung.", "id-ID": "Latih menjelaskannya dengan suara keras seolah sedang sesi live."}'::jsonb, '{"role.live_host": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E10'), 3, '{"en": "Arrange the information into a clear step-by-step presentation.", "ms-MY": "Susun maklumat itu menjadi pembentangan langkah demi langkah yang jelas.", "id-ID": "Susun informasinya menjadi presentasi langkah demi langkah yang jelas."}'::jsonb, '{"role.presenter": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E10'), 4, '{"en": "Focus on the questions needed to match the right information to each buyer.", "ms-MY": "Fokus pada soalan yang perlu untuk memadankan maklumat yang betul dengan setiap pembeli.", "id-ID": "Fokus pada pertanyaan yang diperlukan untuk mencocokkan informasi yang tepat bagi tiap pembeli."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E11', 'scenario', '{"en": "A lead says the first project you recommended does not suit them. What would you naturally do?", "ms-MY": "Lead berkata projek pertama yang anda syorkan tidak sesuai untuk mereka. Apakah yang anda akan buat?", "id-ID": "Sebuah lead mengatakan proyek pertama yang Anda rekomendasikan tidak cocok. Apa yang Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 10);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E11'), 1, '{"en": "Ask more questions and understand what did not match.", "ms-MY": "Tanya lebih lanjut dan fahami apa yang tidak sepadan.", "id-ID": "Ajukan lebih banyak pertanyaan dan pahami apa yang tidak cocok."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E11'), 2, '{"en": "Search for a more suitable option based on the new information.", "ms-MY": "Cari pilihan yang lebih sesuai berdasarkan maklumat baharu itu.", "id-ID": "Cari opsi yang lebih sesuai berdasarkan informasi baru itu."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E11'), 3, '{"en": "Continue the conversation and secure agreement on the next action.", "ms-MY": "Teruskan perbualan dan dapatkan persetujuan untuk tindakan seterusnya.", "id-ID": "Lanjutkan percakapan dan dapatkan kesepakatan untuk tindakan berikutnya."}'::jsonb, '{"role.closer": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E11'), 4, '{"en": "Place the lead into a structured future follow-up plan.", "ms-MY": "Letakkan lead itu dalam pelan susulan berstruktur untuk masa hadapan.", "id-ID": "Masukkan lead itu ke dalam rencana tindak lanjut terstruktur."}'::jsonb, '{"role.prospector": 2, "role.relationship_builder": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='E'), 'E12', 'scenario', '{"en": "You have only 20 minutes to prepare before meeting a potential buyer. What would you focus on first?", "ms-MY": "Anda hanya ada 20 minit untuk bersedia sebelum bertemu bakal pembeli. Apakah tumpuan pertama anda?", "id-ID": "Anda hanya punya 20 menit untuk bersiap sebelum bertemu calon pembeli. Apa fokus pertama Anda?"}'::jsonb, null, 'role', false, true, true, null, 11);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E12'), 1, '{"en": "Review the buyer''s needs and your previous conversation.", "ms-MY": "Semak keperluan pembeli dan perbualan anda sebelum ini.", "id-ID": "Tinjau kebutuhan pembeli dan percakapan Anda sebelumnya."}'::jsonb, '{"role.relationship_builder": 3}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E12'), 2, '{"en": "Select the most relevant project facts and supporting materials.", "ms-MY": "Pilih fakta projek dan bahan sokongan yang paling relevan.", "id-ID": "Pilih fakta proyek dan materi pendukung yang paling relevan."}'::jsonb, '{"role.presenter": 3}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E12'), 3, '{"en": "Prepare your questions and a clear desired next step.", "ms-MY": "Sediakan soalan anda dan langkah seterusnya yang jelas.", "id-ID": "Siapkan pertanyaan Anda dan langkah berikutnya yang jelas."}'::jsonb, '{"role.closer": 3}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='v1' and q.code='E12'), 4, '{"en": "Confirm any financing-process information that may need an authorised specialist.", "ms-MY": "Sahkan maklumat proses pembiayaan yang mungkin memerlukan pakar yang diiktiraf.", "id-ID": "Konfirmasi informasi proses pembiayaan yang mungkin perlu spesialis resmi."}'::jsonb, '{"role.financing_coordinator": 3}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='F'), 'F1', 'text', '{"en": "What does success mean to you personally?", "ms-MY": "Apakah maksud kejayaan bagi anda secara peribadi?", "id-ID": "Apa arti kesuksesan bagi Anda secara pribadi?"}'::jsonb, null, 'reflection', false, false, false, 1500, 0);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='F'), 'F2', 'text', '{"en": "What are you willing to do consistently for the next 12 months to achieve it?", "ms-MY": "Apakah yang anda sanggup lakukan secara konsisten dalam 12 bulan akan datang untuk mencapainya?", "id-ID": "Apa yang bersedia Anda lakukan secara konsisten selama 12 bulan ke depan untuk mencapainya?"}'::jsonb, null, 'reflection', false, false, false, 1500, 1);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='v1' and s.code='F'), 'F3', 'text', '{"en": "What usually causes you to stop, delay, or lose confidence?", "ms-MY": "Apakah yang biasanya menyebabkan anda berhenti, bertangguh atau hilang keyakinan?", "id-ID": "Apa yang biasanya membuat Anda berhenti, menunda, atau kehilangan kepercayaan diri?"}'::jsonb, null, 'reflection', false, false, false, 1500, 2);
